      hx: [['Bowels', 'Normally every 2–3 days; nothing for 8 days now. Hard pellets before that.', 1, 'Bristol 1–2.'], ['Leaking', 'Watery stuff leaks out.', 1, 'Overflow diarrhoea around impaction.'], ['Vomiting / distension', 'No vomiting. Passing wind.', 1, 'Vomiting + absolute constipation + distension = obstruction.'], ['Blood / weight', 'No blood. Weight stable.', 1, 'Red flags.'], ['Urine', 'Hard to pass urine since yesterday.', 0, 'Urinary retention from impaction.'], ['Medicines', 'Codeine 3 times a day for my knees, iron tablets, amlodipine.', 1], ['Thyroid symptoms', 'Always cold, dry skin.', 0]],
      ex: [['Abdomen', 'Mild distension; indentable faecal masses left iliac fossa; bowel sounds present. Palpable bladder.', 1], ['Abdomen (DRE)', 'Rectum loaded with hard stool; normal tone; no mass; no blood.', 1], ['Neurological', 'Mildly confused (delirium).', 0]],
      res: {AXR: 'Extensive faecal loading of the colon and rectum. No dilated small-bowel loops, no air-fluid levels.', DIP: 'Normal.'},
