      hx: [['Pattern', 'Solids first, now soft foods too; it\'s getting worse every month.', 1, 'Progressive solids → liquids = mechanical obstruction.'], ['Level', 'It sticks behind the middle of my breastbone.', 1], ['Weight', 'Lost about 12 kg.', 1], ['Choking / coughing on swallowing', 'Sometimes I cough when it comes back up.', 0, 'Aspiration / tracheo-oesophageal fistula.'], ['Pain on swallowing', 'Not really painful.', 0, 'Odynophagia → candida/CMV/HSV.'], ['Heartburn history', 'Not much heartburn.', 0], ['Voice', 'Hoarse recently.', 0, 'Recurrent laryngeal nerve involvement.']],
      ex: [['General (end of bed)', 'Wasted, dehydrated.', 1], ['Head & neck', 'Hard left supraclavicular node.', 1], ['Abdomen', 'Scaphoid; no hepatomegaly.', 0]],
