      v: severe ? {hr: 124, sbp: 92, dbp: 56, rr: 28, sat: 91, t: 38.2, gcs: 15} : {hr: 104, sbp: 126, dbp: 78, rr: 20, sat: 97, t: 37.6, gcs: 15}, signs: ['pain', 'sweaty'], flags: {pancreatitis: true, alcohol: cause === 'alcohol', hypovolaemic: severe},
      lab: {Lipase: [600, 2600], Amyl: [500, 1800], WCC: severe ? [16, 22] : [11, 14], Ca: severe ? [1.82, 1.98] : [2.15, 2.3], Gluc: severe ? [11, 15] : [7, 9], Urea: severe ? [17, 24] : [5, 8], LDH: severe ? [650, 900] : [240, 400], Alb: severe ? [26, 31] : [34, 38], ALT: cause === 'stones' ? [180, 360] : [40, 80], CRP: severe ? [180, 320] : [40, 110], pO2: severe ? [7.2, 7.9] : [10.5, 12], TG: cause === 'tg' ? [14, 28] : [1.2, 2.2], GGT: cause === 'alcohol' ? [220, 480] : [40, 90]},
      prof: [[`${age}-year-old ${sex === 'M' ? 'man' : 'woman'}`, 1, 'Men 30–50 (alcohol); women 50–70 (gallstones).'], [cause === 'alcohol' ? 'Drinks heavily, binge this weekend' : cause === 'stones' ? 'Known gallstones' : 'Triglycerides very high', 1, 'The cause.'], ['On azathioprine? No.', 0, 'Drugs: azathioprine, valproate, thiazides.'], ['Likes fishing', 0, '—']],
      hx: [['Pain', 'Severe, constant, upper middle, through to the back, better leaning forward.', 1], ['Vomiting', 'Vomiting repeatedly.', 1], ['Alcohol', cause === 'alcohol' ? 'Two bottles of brandy over the weekend.' : 'Hardly drink.', cause === 'alcohol' ? 1 : 0], ['Gallstones', cause === 'stones' ? 'They found stones on a scan last year.' : 'No.', cause === 'stones' ? 1 : 0], ['Breathing', severe ? 'Short of breath.' : 'Fine.', severe ? 1 : 0, 'ARDS.'], ['Urine', severe ? 'Hardly passing urine.' : 'Normal.', severe ? 1 : 0, 'AKI.'], ['Medicines', 'No new medicines.', 0]],
      ex: [['Abdomen', `Epigastric tenderness and guarding, reduced bowel sounds (ileus). ${severe && r.chance(0.5) ? 'Periumbilical bruising (Cullen\'s) and flank bruising (Grey Turner\'s).' : ''}`, 1], ['General (end of bed)', 'Sitting forward, distressed, sweaty.', 1], ['Respiratory', severe ? 'Reduced air entry at the left base.' : 'Clear.', 0]],
      res: {USABD: cause === 'stones' ? 'Gallstones; CBD 7 mm; bulky oedematous pancreas.' : 'No gallstones; pancreas poorly seen (bowel gas).', CTABD: severe ? 'Necrotising pancreatitis (~40% non-enhancement), peripancreatic collections. (CT best after 72 h.)' : 'Interstitial oedematous pancreatitis.', PANEL_ABG: severe ? 'PaO₂ low.' : null},
      cxr: severe ? {effusion: {side: 'left', size: 'small'}, consol: [{lobe: 'LLL', dens: 0.5}]} : {},
