  must: [{k: 'fluid', n: 'Goal-directed IV fluids (Ringer\'s lactate)', why: 'Third-space losses; monitor urine output.'}, {k: 'opioid', n: 'Analgesia (opioids fine)', why: 'Severe pain.'}, {k: 'o2', n: 'Oxygen', why: 'ARDS risk.'}],
